mapper.select:
SELECT s.id, s.layout_version_id, s.parent_simulation_id, s.created_by, s.status, s.created_at, so.total_people FROM simulations s JOIN simulation_options so ON so.simulation_id = s.id WHERE s.layout_version_id = #{layoutVersionId}
AND s.created_by = #{createdBy}
ORDER BY s.created_at DESC, s.id DESC

SELECT agent_positions
FROM simulation_initial_states
WHERE simulation_id = #{simulationId}

mapper.update:
UPDATE simulation_options
SET total_people = #{totalPeople},
    walking_speed = #{walkingSpeed},
    reaction_time = #{reactionTime}
WHERE simulation_id = #{simulationId}

UPDATE simulation_initial_states
SET agent_positions = CAST(#{agentPositions} AS JSON)
WHERE simulation_id = #{simulationId}
